HOST, PORT = 'evalme', 1337

def attempt(tag):
    s = socket.create_connection((HOST, PORT), timeout=5)
    s.settimeout(5)
    buf = b''
    correct = 0
    log = []
    t0 = time.time()
    while True:
        if b'\n' not in buf:
            try:
                chunk = s.recv(8192)
            except socket.timeout:
                log.append((tag, 'SOCKET_TIMEOUT', correct))
                break
            if not chunk:
                log.append((tag, 'EOF', correct))
                break
            buf += chunk
            continue
        line, buf = buf.split(b'\n', 1)
        text = line.decode('utf-8', 'replace').strip()
        if not text:
            continue
        log.append((tag, 'S', text))
        if 'SEKAI{' in text:
            print('FLAGLINE', text, flush=True)
            try:
                s.close()
            except Exception:
                pass
            return text, correct, log
        if text == 'correct':
            correct += 1
            continue
        if text in ('Too slow', 'incorrect'):
            # incorrect: keep going; too slow: server may close
            if text == 'Too slow':
                break
            continue
        # arithmetic?
        if re.fullmatch(r'-?\d+(?:\.\d+)?\s*[+\-*/]\s*-?\d+(?:\.\d+)?', text):
            try:
                ans = eval(text)
            except Exception:
                continue
            s.sendall(repr(ans).encode() + b'\n')
    try:
        s.close()
    except Exception:
        pass
    return None, correct, log

for i in range(5):
    flag, correct, log = attempt(i)
    print(f'attempt {i}: correct={correct} flag={flag!r} elapsed_tail_lines={log[-3:]}', flush=True)
    if flag:
        print('FOUND', flag, flush=True)
        break
