{"content": "import socket, re, sys, time

ARITH = re.compile(r'^-?\d+(?:\.\d+)?\s*[+\-*/]\s*-?\d+(?:\.\d+)?$')
BANNER = ('Welcome', 'I will send', 'Do it 100')

s = socket.create_connection(('evalme', 1337), timeout=5)
s.settimeout(6)
buf = b''
correct = 0
special_done = False
raw = bytearray()
done_nice = False
t_start = time.time()
while True:
    if b'\n' not in buf:
        try:
            chunk = s.recv(8192)
        except socket.timeout:
            print('SOCKET_TIMEOUT at', round(time.time()-t_start, 3), flush=True)
            break
        if not chunk:
            print('EOF at', round(time.time()-t_start, 3), flush=True)
            break
        raw += chunk
        buf += chunk
        continue
    line, buf = buf.split(b'\n', 1)
    t = line.decode('utf-8', 'replace').strip()
    if not t:
        continue
    if t.startswith(BANNER):
        continue
    if t == 'correct':
        correct += 1
        continue
    if t == 'Nice!!':
        done_nice = True
        print('GOT Nice!! at', round(time.time()-t_start, 3), 'correct', correct, flush=True)
        # wait for possible flag data
        time.sleep(2.0)
        try:
            while True:
                chunk = s.recv(8192)
                if not chunk:
                    print('EOF after Nice at', round(time.time()-t_start, 3), flush=True)
                    break
                raw += chunk
                print('POST-NICE CHUNK', chunk, flush=True)
        except socket.timeout:
            print('post-Nice timeout', flush=True)
        try:
            s.sendall(b'\n')
        except Exception as e:
            print('send newline failed', e, flush=True)
        time.sleep(1.0)
        try:
            chunk = s.recv(8192)
            print('AFTER NEWLINE', chunk, flush=True)
        except socket.timeout:
            print('after newline timeout', flush=True)
        break
    if ARITH.match(t):
        s.sendall(repr(eval(t)).encode() + b'\n')
        continue
    if t in ('incorrect', 'Too slow'):
        print('STATUS', t, 'after', correct, flush=True)
        continue
    # special polluted question
    print('SPECIAL after', correct, ':', repr(t[:60]), flush=True)
    if not special_done:
        special_done = True
        s.sendall(b"b''\n")
    else:
        s.sendall(b'0\n')

print('DONE correct=', correct, 'nice=', done_nice, flush=True)
print('RAW TAIL:', bytes(raw[-400:]), flush=True)
try:
    s.close()
except Exception:
    pass
